from collections import Counter

rows = []
for s in open('9-251.csv'):
    rows.append([int(x) for x in s.split(';')])
cols = [Counter(row[i] for row in rows) for i in range(len(rows[0]))]
count = 0
for row in rows:
    mean = sum(row) / len(row)
    interesting = 0
    for i, x in enumerate(row):
        if row.count(x) == 1 and cols[i][x] - 1 >= 30 and x > mean:
            interesting += 1
    if interesting == 1:
        count += 1
print(count)

